// Small stand-in for the snapshot tool; real JobDB snapshots are checked separately.
package main
import ("bytes"; "flag"; "fmt"; "os")
func main() {
    packages := flag.String("packages", "", "fixture package list")
    check := flag.String("check", "", "fixture snapshot")
    flag.Parse()
    paths, err := os.ReadFile(*packages)
    if err != nil || string(paths) != "example.com/jobdbverifyfixture\n" { fmt.Fprintln(os.Stderr, "invalid fixture package inventory"); os.Exit(1) }
    raw, err := os.ReadFile(*check)
    if err != nil || !bytes.Equal(raw, []byte("fixture public API\n")) { fmt.Fprintln(os.Stderr, "fixture API snapshot differs"); os.Exit(1) }
}

