//go:build race

package fixture

import (
 "flag"
 "runtime"
 "testing"
 "time"
)

func TestRaceBudget(t *testing.T) {
 if got := runtime.GOMAXPROCS(0); got != 2 {
  t.Fatalf("GOMAXPROCS = %d, want 2", got)
 }
 if got := flag.Lookup("test.parallel").Value.String(); got != "2" {
  t.Fatalf("test parallelism = %s, want 2", got)
 }
 deadline, ok := t.Deadline()
 if !ok {
  t.Fatal("race suite must have a package timeout")
 }
 if left := time.Until(deadline); left < 19*time.Minute || left > 20*time.Minute {
  t.Fatalf("remaining race timeout = %s, want between 19m and 20m", left)
 }
}

